#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("INVALID_INPUT");
        return 0;
    }
    const char *input = argv[1];
    size_t len = strlen(input);
    if (len == 0 || len > 31) {
        puts("INVALID_INPUT");
        return 0;
    }
    for (size_t i = 0; i < len; ++i) {
        if (input[i] != '0' && input[i] != '1') {
            puts("INVALID_INPUT");
            return 0;
        }
    }
    char tape[32];
    memcpy(tape, input, len);
    int steps = 0;
    int head = 0; // start at leftmost cell
    // move right to the end of the input
    while (head < (int)len) {
        head++;
        steps++;
    }
    // move left, flipping bits until a '0' is found
    while (head > 0) {
        head--;
        steps++;
        if (tape[head] == '0') {
            tape[head] = '1';
            // set all bits to the right of the changed position to '0'
            for (int i = head + 1; i < (int)len; ++i) {
                tape[i] = '0';
            }
            printf("result=");
            fwrite(tape, 1, len, stdout);
            printf(" steps=%d\n", steps);
            return 0;
        } else { // tape[head] == '1'
            tape[head] = '0';
        }
    }
    // If we reach here, all bits were '1' -> overflow
    puts("OVERFLOW");
    printf(" steps=%d\n", steps);
    return 0;
}
